    # Outils publics — publication de posts
    # ------------------------------------------------------------------
    @staticmethod
    def _post_length(text: str) -> int:
        """Longueur pondérée façon X : caractères latins = 1, autres (emoji, CJK…) = 2. URLs non comptées à 23."""
        latin = ((0, 4351), (8192, 8205), (8208, 8223), (8242, 8247))
        return sum(1 if any(a <= ord(c) <= b for a, b in latin) else 2 for c in text)

    def _post_failure_notice(self, result: Dict[str, Any]) -> None:
        if not result.get("ok") and result.get("status_code") in (401, 403):
            result["notice"] = (
                "Publier ou supprimer un post exige un contexte utilisateur : soit les 4 clés "
                "OAuth 1.0a dans les Valves (X_API_KEY, X_API_SECRET, X_OAUTH1_ACCESS_TOKEN, "
                "X_OAUTH1_ACCESS_SECRET), soit un token OAuth 2.0 user-context (tweet.read, "
                "tweet.write, users.read) dans X_ACCESS_TOKEN. Un token app-only ne peut pas publier. "
                f"Mode utilisé : {'OAuth 1.0a' if self._oauth1_configured() else 'Bearer'}."
            )

    def create_post(
        self,
        text: str,
        reply_to_post_id: Optional[str] = None,
        quote_post_id: Optional[str] = None,
        media_ids: Optional[str] = None,
        confirm: bool = False,
    ) -> str:
        """
        Publie un post sur X (POST /2/tweets). Action publique et visible : sans confirm=true,
        renvoie seulement un aperçu (longueur, corps de la requête) et ne publie rien.
        :param text: Texte du post.
        :param reply_to_post_id: ID d'un Post auquel répondre (optionnel).
        :param quote_post_id: ID d'un Post à citer (optionnel).
        :param media_ids: IDs de médias déjà téléversés, séparés par des virgules (optionnel).
        :param confirm: Mettre true pour publier réellement.
        """
        text = (text or "").strip()
        ids = [m.strip() for m in (media_ids or "").split(",") if m.strip()]
        if not text and not ids:
            return self._dump(
                {"ok": False, "error": "Fournissez un texte ou des media_ids."}
            )

        length = self._post_length(text)
        limit = int(self.valves.MAX_POST_LENGTH)
        if length > limit:
            return self._dump(
                {
                    "ok": False,
                    "error": f"Post trop long : {length} caractères pondérés pour {limit} autorisés.",
                }
            )
        for label, value in (
            ("reply_to_post_id", reply_to_post_id),
            ("quote_post_id", quote_post_id),
        ):
            if value and not value.strip().isdigit():
                return self._dump(
                    {
                        "ok": False,
                        "error": f"{label} doit être un identifiant numérique.",
                    }
                )
        if ids and not all(i.isdigit() for i in ids):
            return self._dump(
                {
                    "ok": False,
                    "error": "media_ids doit contenir des identifiants numériques.",
                }
            )
        if len(ids) > 4:
            return self._dump({"ok": False, "error": "4 médias maximum par post."})

        body: Dict[str, Any] = {}
        if text:
            body["text"] = text
        if reply_to_post_id:
            body["reply"] = {"in_reply_to_tweet_id": reply_to_post_id.strip()}
        if quote_post_id:
            body["quote_tweet_id"] = quote_post_id.strip()
        if ids:
            body["media"] = {"media_ids": ids}

        if not confirm:
            return self._dump(
                {
                    "ok": True,
                    "preview": True,
                    "weighted_length": f"{length}/{limit} (hors URLs, comptées 23 par X)",
                    "request_body": body,
                    "message": "Aperçu seulement. Relancez avec confirm=true pour publier.",
                }
            )

        result = self._call(
            "POST",
            "",
            json_body=body,
            base=self.valves.X_POSTS_BASE.strip().rstrip("/"),
            auth=self._post_auth_mode(),
        )
        if result.get("ok"):
            data = result.get("data")
            post_id = (
                data.get("data", {}).get("id")
                if isinstance(data, dict) and isinstance(data.get("data"), dict)
                else None
            )
            if post_id:
                result["url"] = f"https://x.com/i/status/{post_id}"
        self._post_failure_notice(result)
        return self._dump(result)

    def delete_post(self, post_id: str, confirm: bool = False) -> str:
        """
        Supprime un de vos posts (DELETE /2/tweets/:id). Sans confirm=true, renvoie seulement un aperçu.
        :param post_id: ID numérique du Post à supprimer.
        :param confirm: Mettre true pour supprimer réellement.
        """
        post_id = (post_id or "").strip()
        if not post_id.isdigit():
            return self._dump(
                {"ok": False, "error": "post_id doit être un identifiant numérique."}
            )
        if not confirm:
            return self._dump(
                {
                    "ok": True,
                    "preview": True,
                    "message": f"Le post {post_id} serait supprimé. Relancez avec confirm=true pour confirmer.",
                }
            )
        result = self._call(
            "DELETE",
            f"/{post_id}",
            base=self.valves.X_POSTS_BASE.strip().rstrip("/"),
            auth=self._post_auth_mode(),
        )
        self._post_failure_notice(result)
        return self._dump(result)

    def verify_credentials(self) -> str:
        """
        Vérifie les identifiants de publication sans rien publier : renvoie le compte X (@handle)
        associé aux clés, et le mode d'authentification utilisé (OAuth 1.0a ou Bearer).
        À lancer avant le premier post pour confirmer que les clés sont bien celles de @hq_wire.
        """
        mode = self._post_auth_mode()
        result = self._call("GET", "", base=self.USERS_ME_URL, auth=mode)
        result["auth_mode"] = (
            "OAuth 1.0a" if mode == "oauth1" else "Bearer (X_ACCESS_TOKEN)"
        )
        data = result.get("data")
        user = data.get("data") if isinstance(data, dict) else None
        if result.get("ok") and isinstance(user, dict) and user.get("username"):
            result["account"] = f"@{user['username']}"
        elif not result.get("ok"):
            result["notice"] = (
                "Échec de la vérification. Si le statut est 401 : clés incorrectes ou mal copiées. "
                "Si 403 : app non autorisée, ou token app-only (incapable de publier)."
            )
        return self._dump(result)

    # ------------------------------------------------------------------
    # Outils publics — flux temps réel
    # ------------------------------------------------------------------
    @staticmethod
    def _find_event_type(event: dict) -> Optional[str]:
        """Cherche le type d'un événement reçu (racine ou sous l'objet 'data')."""
        if not isinstance(event, dict):
            return None
        for container in (event, event.get("data")):
            if isinstance(container, dict):
                for key in ("event_type", "type"):
                    if isinstance(container.get(key), str):
                        return container[key]
        return None

    def _collect_stream(
        self, duration_seconds: int, max_events: int, event_type: Optional[str]
    ) -> Dict[str, Any]:
        """Lit le flux (bloquant) ; un minuteur ferme la connexion à l'échéance exacte."""
        url = f"{self._base_url()}/stream"
        events: List[dict] = []
        skipped = 0
        started = time.time()
        deadline = started + duration_seconds
        timer = None
        try:
            with requests.get(
                url,
                headers=self._headers(),
                stream=True,
                timeout=(10, duration_seconds + 30),
            ) as resp:
                if resp.status_code != 200:
                    out = {
                        "ok": False,
                        "status_code": resp.status_code,
                        "data": resp.text[:2000],
                    }
                    hint = self._status_hint(resp.status_code)
                    if hint:
                        out["hint"] = hint
                    return out
                timer = threading.Timer(duration_seconds, resp.close)
                timer.daemon = True
                timer.start()
                try:
                    for line in resp.iter_lines(decode_unicode=True):
                        if time.time() >= deadline:
                            break
                        if not line:  # keep-alive
                            continue
                        line = line.strip()
                        if line.startswith("data:"):  # compat SSE
                            line = line[5:].strip()
                        if not line:
                            continue
                        try:
                            event = json.loads(line)
                        except json.JSONDecodeError:
                            event = {"raw": line}
                        if event_type and self._find_event_type(event) != event_type:
                            skipped += 1
                            continue
                        events.append(event)
                        if len(events) >= max_events:
                            break
                except (requests.RequestException, ValueError, OSError):
                    # Fermeture volontaire à l'échéance ou coupure de lecture : fin normale.
                    if time.time() < deadline - 1 and not events:
                        raise
        except RuntimeError as e:
            return {"ok": False, "error": str(e)}
        except requests.RequestException as e:
            return {"ok": False, "error": f"Erreur réseau : {e}"}
        finally:
            if timer:
                timer.cancel()

        out = {
            "ok": True,
            "event_count": len(events),
            "duration_seconds": round(time.time() - started, 1),
            "reached_max_events": len(events) >= max_events,
            "events": events,
        }
        if event_type:
            out["filtered_out"] = skipped
        return out

    async def connect_stream(
        self,
        duration_seconds: int = 60,
        max_events: int = 20,
        event_type: Optional[str] = None,
        __event_emitter__=None,
    ) -> str:
        """
        Se connecte au flux d'activité persistant (GET /2/activity/stream) et collecte les événements reçus.
        Ne reçoit que les événements des abonnements créés SANS webhook_id.
        :param duration_seconds: Durée d'écoute en secondes (1 à la limite des Valves, défaut 60).
        :param max_events: Nombre maximal d'événements à collecter avant de rendre la main (défaut 20).
        :param event_type: Filtre optionnel appliqué côté outil : ne garder que ce type d'événement.
        """

        async def status(description: str, done: bool = False):
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {"description": description, "done": done},
                    }
                )

        if event_type:
            try:
                self._validate_event_type(event_type)
            except ValueError as e:
                return self._dump({"ok": False, "error": str(e)})

        duration_seconds = max(
            1, min(int(duration_seconds), int(self.valves.MAX_STREAM_SECONDS))
        )
        max_events = max(1, min(int(max_events), int(self.valves.MAX_STREAM_EVENTS)))

        await status(f"Écoute du flux X Activity ({duration_seconds} s max)…")
        result = await asyncio.to_thread(
            self._collect_stream, duration_seconds, max_events, event_type
        )
        if result.get("ok"):
            await status(
                f"Flux terminé : {result['event_count']} événement(s) reçu(s).",
                done=True,
            )
        else:
            await status("Échec de la connexion au flux.", done=True)
        return self._dump(result)

    # ------------------------------------------------------------------
    # Helpers standards du template OpenWebUI
    # ------------------------------------------------------------------
    def get_user_name_and_email_and_id(self, __user__: dict = {}) -> str:
        """Get the user name, Email and ID from the user object."""
        result = ""
        if "name" in __user__:
            result += f"User: {__user__['name']}"
        if "id" in __user__:
            result += f" (ID: {__user__['id']})"
        if "email" in __user__:
            result += f" (Email: {__user__['email']})"
        return result or "User: Unknown"

    def get_current_time(self) -> str:
        """Get the current date and time (local and UTC), useful to build expires_at values."""
        now = datetime.now().astimezone()
        utc = now.astimezone(timezone.utc)
        return (
            f"Local: {now.strftime('%A, %B %d, %Y, %I:%M:%S %p')} | "
            f"UTC (RFC 3339): {utc.strftime('%Y-%m-%dT%H:%M:%SZ')}"
        )
